from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.errors import BillingError
from ledgerly.models import Payment

T0 = datetime(2026, 10, 1, tzinfo=timezone.utc)

def pay(amount="5000.00", status="captured"):
    return Payment("pay_1", "inv_1", Decimal(amount), status=status, created_at=T0, captured_at=T0)

# at threshold: no approval needed
p = pay(); outage_refund(p, Decimal("1000.00"), T0); print("at threshold ok", p.refunded_amount)
# above threshold without approval -> error
p = pay()
try: outage_refund(p, Decimal("1000.01"), T0)
except BillingError as e: print("above no approval:", e.code, "refunded unchanged:", p.refunded_amount)
# above threshold with approval -> ok
p = pay(); outage_refund(p, Decimal("1000.01"), T0, approved_by="mgr"); print("approved ok", p.refunded_amount)
# full refund sets status
p = pay("80.00"); outage_refund(p, Decimal("80.00"), T0); print("full:", p.refunded_amount, p.status)
# partial keeps captured
p = pay("80.00"); outage_refund(p, Decimal("8.00"), T0); print("partial:", p.refunded_amount, p.status)
# non-captured
try: outage_refund(pay(status="authorized"), Decimal("1"), T0)
except BillingError as e: print("state:", e.code)
# non-positive
try: outage_refund(pay(), Decimal("0"), T0)
except BillingError as e: print("amount:", e.code)
# exceeds captured
try: outage_refund(pay("10.00"), Decimal("11.00"), T0)
except BillingError as e: print("exceeds:", e.code)
EOF"}

